  var CUBE_COL={'Bianco opaco':'#f3f2ee','Rovere sbiancato':'#e4d6bf','Effetto noce':'#7d553a','Marrone-nero':'#3d322b','Grigio legno':'#a8a299','Bianco lucido':'#fdfdfc'};
