    return '<g stroke="'+col+'" stroke-width="1" fill="none"><path d="M'+x+' '+y1+'V'+y2+'"/><path d="M'+(x-6)+' '+y1+'h12M'+(x-6)+' '+y2+'h12"/><path d="M'+(x-3)+' '+(y1+7)+'L'+x+' '+y1+'L'+(x+3)+' '+(y1+7)+'M'+(x-3)+' '+(y2-7)+'L'+x+' '+y2+'L'+(x+3)+' '+(y2-7)+'"/></g>'
