      [[hw,w],[hh,h]].forEach(function(x){x[0].setAttribute('aria-valuemin',x[1].min);x[0].setAttribute('aria-valuemax',x[1].max);x[0].setAttribute('aria-valuenow',x[1].value);x[0].setAttribute('aria-valuetext',x[1].value+' cm')});
