      if(p.custom&&p.limits){var L=p.limits;h+='<figure class="pdp-draw furn note"><div class="pdp-lim"><b>Made to measure</b><span>Width '+L.w[0]+'–'+L.w[1]+' cm</span><span>Depth '+L.d[0]+'–'+L.d[1]+' cm</span><span>Height '+L.h[0]+'–'+L.h[1]+' cm</span><a class="s-link" href="#pdp-cfg">Enter your sizes ↑</a></div><figcaption><b>Built to the centimetre</b><span>+'+PR.furniture.customPerc+'% on the price, in proportion</span></figcaption></figure>'}
